// Turns ingest_heartbeat / offline_check results into one Telegram message per event.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cairo = (t) => new Date(t || Date.now()).toLocaleString('en-GB', {
  timeZone: 'Africa/Cairo', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit', hour12: false,
}) + ' Cairo';
const dur = (s) => {
  s = Math.max(0, Math.round(Number(s) || 0));
  const d = Math.floor(s / 86400), h = Math.floor((s % 86400) / 3600), m = Math.floor((s % 3600) / 60);
  if (d) return `${d}d ${h}h`;
  if (h) return `${h}h ${m}m`;
  return m ? `${m}m` : `${s}s`;
};
const out = [];
for (const item of $input.all()) {
  let r = item.json.result;
  if (typeof r === 'string') r = JSON.parse(r);
  const events = Array.isArray(r) ? r : (r && r.events) || [];
  for (const e of events) {
    const who = `<b>${esc(e.hostname)}</b>` + (e.client ? ` (${esc(e.client)})` : '');
    let text;
    if (e.kind === 'alert') {
      text = `🔴 CRITICAL · ${who}\n${esc(e.title)}` + (e.detail ? `\n${esc(e.detail)}` : '') + `\n${cairo(e.at)}`;
    } else if (e.kind === 'resolved') {
      text = `✅ RESOLVED · <b>${esc(e.hostname)}</b>\n${esc(e.title)}\nLasted ${dur(e.duration_s)} · ${cairo(e.at)}`;
    } else if (e.kind === 'offline') {
      text = `⚫ SERVER OFFLINE · ${who}\nNo heartbeat for ${dur(e.silent_s)} (last ${cairo(e.last_heartbeat_at)})`;
    } else if (e.kind === 'online') {
      const off = e.offline_since ? Date.parse(e.last_heartbeat_at) - Date.parse(e.offline_since) : 0;
      text = `🟢 BACK ONLINE · ${who}\nHeartbeat again at ${cairo(e.last_heartbeat_at)}` + (off > 0 ? ` (offline alert was ${dur(off / 1000)} earlier)` : '');
    } else continue;
    out.push({ json: { text, kind: e.kind, hostname: e.hostname, key: e.key } });
  }
}
return out;
